<template>
  <el-card shadow="never" style="position: relative; width: 40vw; border-radius: 15px; margin-left: 5vw;">
    <el-tag class="indicator" v-if="book['Tinh trang'] !== '0'" type='danger' effect="dark">
      Đang mượn
    </el-tag>
      
    <el-row>
      <el-col :span="7">
        <div class="cover-wrapper">
          <svg width='6' height='150' viewBox='0 0 6 150' fill='none' xmlns='http://www.w3.org/2000/svg'
            style="position: absolute; z-index: 1;">
            <rect width='6' height='150' fill='url(#paint0_linear)'/>
            <defs>
              <linearGradient id='paint0_linear' x1='6' y1='61.5234' x2='-9.54301e-06' y2='61.5315' gradientUnits='userSpaceOnUse'>
                <stop stop-color='white' stop-opacity='0'/>
                <stop offset='0.139111' stop-color='white' stop-opacity='0.2'/>
                <stop offset='0.290477' stop-opacity='0.18'/>
                <stop offset='0.726819' stop-color='#D8D8D8' stop-opacity='0.273181'/>
                <stop offset='0.839352' stop-opacity='0.15'/>
                <stop offset='1' stop-opacity='0.19'/>
              </linearGradient>
            </defs>
          </svg>
          <el-image :src="`/api/books/cover/${book['So Tai san']}.jpg`" alt="cover" lazy style="width: 100px; height:150px;">
            <template #error>
              <div class="none-cover covered">
                <div class="c-book">
                  <div class="book-title" style="font-weight: bold; font-size: 10px; margin-top: 15px; margin-left: 10px; margin-right: 5px;">
                    {{ book['Tua'] }}
                  </div>
                  <div class="c-book-authors">
                    {{ ((book['Ten Tac gia'].endsWith(' ') || book['Ten Tac gia'].endsWith(',')) ? book['Ten Tac gia'].slice(0,-1) : book['Ten Tac gia']) 
                      + ((book['Ten Tac gia'] !== '' & book['Ho Tac gia'] !== '') ? ', ' : '') + book['Ho Tac gia'] }}
                  </div>
                </div>
              </div>
            </template>
          </el-image>
        </div>
      </el-col>
      <el-col :span="17">
        <el-row>
          <el-col :span="17">
            <el-row>
              <div class="book-title" :title="book['Tua']" style="font-weight: bold; font-size: 18px; margin-bottom: 5px;">{{ book['Tua'] }}</div>
            </el-row>
            <el-row style="opacity: 0.7; font-weight: 300; font-size: 12px; margin-bottom: 5px;">
              {{ (book['Noi Xb'].endsWith(' ') ? book['Noi Xb'].slice(0,-1) : book['Noi Xb']) 
                + (book['Noi Xb'] !== '' ? ': ' : '') 
                + (book['Nha Xb'].endsWith(' ') ? book['Nha Xb'].slice(0,-1) : book['Nha Xb']) 
                + ((book['Nha Xb'] !== '' & book['Nam Xb'] !== '') ? ', ' : '') 
                + book['Nam Xb'] }}
            </el-row>
            <el-row style="font-weight: 300; font-style: italic; font-size: 14px;">
              {{ ((book['Ten Tac gia'].endsWith(' ') || book['Ten Tac gia'].endsWith(',')) ? book['Ten Tac gia'].slice(0,-1) : book['Ten Tac gia']) 
                  + ((book['Ten Tac gia'] !== '' & book['Ho Tac gia'] !== '') ? ', ' : '') + book['Ho Tac gia'] }}
            </el-row>
          </el-col>
          <el-col :span="7">
            <el-row justify="end">{{ book['So Chu de'] }}</el-row>
            <el-row justify="end">{{ book['So Tac gia'] }}</el-row>
            <el-row justify="end">{{ book['So Tai san'] }}</el-row>
          </el-col>
        </el-row>
        
        <el-link type="primary" style="position: absolute; bottom: 5px; right: 10px;" @click="detailDialog = !detailDialog">Chi tiết...</el-link>
      </el-col>
    </el-row>
  </el-card>

  <el-dialog v-model="detailDialog" :show-close="true" width="80%" top>
    <el-row>
      <el-col :span="7">
        <el-image :src="`/api/books/cover/${book['So Tai san']}.jpg`" alt="cover" lazy style="width: 250px; height:375px;">
          <template #error>
            <el-empty description="Đang cập nhật..." />
          </template>
        </el-image>
      </el-col>
      <el-col :span="17">
        <el-descriptions
          :title="book['Tua']"
          :column="1"
          size="large"
          border
        >
        <el-descriptions-item v-if="book['Chu de Tong quat']">
            <template #label>
              <div class="cell-item">
                <el-icon>
                  <star-filled />
                </el-icon>
                Chủ đề
              </div>
            </template>
            {{ book['Chu de Tong quat'] }}
          </el-descriptions-item>
          <el-descriptions-item>
            <template #label>
              <div class="cell-item">
                <el-icon>
                  <user-filled />
                </el-icon>
                Tác giả
              </div>
            </template>
            {{ ((book['Ten Tac gia'].endsWith(' ') || book['Ten Tac gia'].endsWith(',')) ? book['Ten Tac gia'].slice(0,-1) : book['Ten Tac gia']) 
                + ((book['Ten Tac gia'] !== '' & book['Ho Tac gia'] !== '') ? ', ' : '') + book['Ho Tac gia'] }}
          </el-descriptions-item>
          <el-descriptions-item v-if="book['Dich gia']">
            <template #label>
              <div class="cell-item">
                <el-icon>
                  <avatar />
                </el-icon>
                Dịch giả
              </div>
            </template>
            {{ book['Dich gia'] }}
          </el-descriptions-item>
          <el-descriptions-item>
            <template #label>
              <div class="cell-item">
                <el-icon>
                  <location-filled />
                </el-icon>
                Xuất bản
              </div>
            </template>
            {{ (book['Noi Xb'].endsWith(' ') ? book['Noi Xb'].slice(0,-1) : book['Noi Xb']) 
                + (book['Noi Xb'] !== '' ? ': ' : '') 
                + (book['Nha Xb'].endsWith(' ') ? book['Nha Xb'].slice(0,-1) : book['Nha Xb']) 
                + ((book['Nha Xb'] !== '' & book['Nam Xb'] !== '') ? ', ' : '') 
                + book['Nam Xb'] }}
          </el-descriptions-item>
          <el-descriptions-item>
            <template #label>
              <div class="cell-item">
                <el-icon>
                  <info-filled />
                </el-icon>
                Số Chủ đề
              </div>
            </template>
            {{ book['So Chu de'] }}
          </el-descriptions-item>
          <el-descriptions-item>
            <template #label>
              <div class="cell-item">
                <el-icon>
                  <info-filled />
                </el-icon>
                Số Tác giả
              </div>
            </template>
            {{ book['So Tac gia'] }}
          </el-descriptions-item>
          <el-descriptions-item>
            <template #label>
              <div class="cell-item">
                <el-icon>
                  <info-filled />
                </el-icon>
                Số tài sản
              </div>
            </template>
            {{ book['So Tai san'] }}
          </el-descriptions-item>
          <el-descriptions-item v-if="book['So Cuon']">
            <template #label>
              <div class="cell-item">
                <el-icon>
                  <info-filled />
                </el-icon>
                Số cuốn
              </div>
            </template>
            {{ book['So Cuon'] }}
          </el-descriptions-item>
          <el-descriptions-item v-if="book['So Tap']">
            <template #label>
              <div class="cell-item">
                <el-icon>
                  <info-filled />
                </el-icon>
                Số tập
              </div>
            </template>
            {{ book['So Tap'] }}
          </el-descriptions-item>
          <el-descriptions-item v-if="book['So trang']">
            <template #label>
              <div class="cell-item">
                <el-icon>
                  <paperclip />
                </el-icon>
                Số trang
              </div>
            </template>
            {{ book['So trang'] }}
          </el-descriptions-item>
          <el-descriptions-item>
            <template #label>
              <div class="cell-item">
                <el-icon>
                  <promotion />
                </el-icon>
                Ngôn ngữ
              </div>
            </template>
            <el-tag size="small">{{ book['Ngon ngu'] }}</el-tag>
          </el-descriptions-item>
        </el-descriptions>
      </el-col>
    </el-row>
    
  </el-dialog>
</template>

<script>
export default {
  name: 'BookCard',
  props: {
    book: Object
  },
  data() {
    return {
      detailDialog: false
    }
  }
}
</script>

<style scoped>
.none-cover {
  width: 100px;
  height: 150px;
  border-bottom: 1px solid rgb(234, 199, 151);
  border-right: 1px solid rgb(255, 224, 176);
}
.covered {
  border-radius: 0 4px 3px 2px;
  padding: 0 2% 2% 0;
  background: #fff;
}
.c-book {
  border: 1px solid #eac797;  
  background: linear-gradient(140deg, #eac797 60%, #ffe0b0 100%);
  border: 1px solid #fff;
  color: #61513b;
  text-align: center;
  line-height: 100%;
  position: relative;
  border-radius: 0 2px 2px 0;
  width: 100%;
  height: 100%;
}
.c-book-authors {
  font-size: 10px;
  margin-top: 80px;
  margin-left: 10px;
  margin-right: 5px;
  font-weight: normal;
  display: block;
  text-overflow: ellipsis;
  overflow: hidden;
  white-space: nowrap;
}
.cover-wrapper {
  position: relative;
  min-width: 100px;
  display: inline-block;
  margin-left: 10px;
}
.book-title {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;  
  overflow: hidden;
}
.indicator {
  position: absolute;
  transform: rotate(-45deg);
  left: -30px;
  top: 15px;
  width: 120px;
  z-index: 2;
}
.el-card {
  --el-card-padding: 10px;
}
</style>